/**
 * Check if a given object implements the FundHolderItem interface.
 */
export function instanceOfFundHolderItem(value) {
    if (!("entityName" in value) || value["entityName"] === undefined)
        return false;
    return true;
}
export function FundHolderItemFromJSON(json) {
    return FundHolderItemFromJSONTyped(json, false);
}
export function FundHolderItemFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        entityName: json["entity_name"],
        dateReported: json["date_reported"] == null ? undefined : json["date_reported"],
        shares: json["shares"] == null ? undefined : json["shares"],
        value: json["value"] == null ? undefined : json["value"],
        percentHeld: json["percent_held"] == null ? undefined : json["percent_held"],
    };
}
export function FundHolderItemToJSON(json) {
    return FundHolderItemToJSONTyped(json, false);
}
export function FundHolderItemToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        entity_name: value["entityName"],
        date_reported: value["dateReported"],
        shares: value["shares"],
        value: value["value"],
        percent_held: value["percentHeld"],
    };
}
